<script setup lang="ts">
import { onMounted,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { Plus,Search } from 'lucide-vue-next';import {vendorAPI} from '../../services/api';import type{VendorProduct} from '../../services/api';import StatusBadge from '../../components/StatusBadge.vue';
const route=useRoute(),router=useRouter(),items=ref<VendorProduct[]>([]),loading=ref(true),error=ref(''),page=ref(1),totalPages=ref(1),q=ref(typeof route.query.q==='string'?route.query.q:''),status=ref(typeof route.query.status==='string'?route.query.status:'');
const statusOptions=['','active','pending','disabled','out_of_stock'];
async function load(){loading.value=true;error.value='';try{const r=await vendorAPI.getProducts({q:q.value,status:status.value,page:page.value,per_page:20});items.value=r.items;totalPages.value=r.totalPages}catch(e:unknown){error.value=e instanceof Error?e.message:'Products could not be loaded.'}finally{loading.value=false}}
watch([q,status],()=>{page.value=1;void router.replace({query:{q:q.value||undefined,status:status.value||undefined,page:page.value>1?String(page.value):undefined}});void load()});
function stockHint(p:VendorProduct){return p.stock===0?'Out of stock':p.stock<=5?`Low stock: ${p.stock}`:''}
function low(p:VendorProduct){return p.stock<=5}onMounted(load)
</script><template><main class="vendor-main"><header class="page-head"><div><p>CATALOGUE</p><h1>My Products</h1></div><div class="head-actions"><router-link to="/vendor/products/upload" class="secondary">Upload products</router-link><router-link to="/vendor/products/new" class="primary"><Plus :size="17"/>Add product</router-link></div></header><div class="filters"><label><Search :size="16"/><input v-model="q" type="search" placeholder="Search products"/></label><select v-model="status"><option value="">All statuses</option><option v-for="value in statusOptions.slice(1)" :key="value" :value="value">{{value==='out_of_stock'?'Out of stock':value}}</option></select></div><div v-if="loading" class="state">Loading products...</div><div v-else-if="error" class="state error">{{error}}</div><div v-else-if="!items.length" class="state">No products found. <router-link to="/vendor/products/new">Add one</router-link>, or <router-link to="/vendor/products/upload">upload many at once</router-link>.</div><div v-else class="product-table"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in items" :key="p.id"><td data-label="Product"><div class="product-name"><img v-if="p.image" :src="p.image" alt=""/><span>{{p.name}}</span></div></td><td data-label="Price">KSh {{Number(p.price).toLocaleString()}}</td><td data-label="Stock" :class="{low:low(p)}">{{stockHint(p)||p.stock}}</td><td data-label="Status"><StatusBadge :status="p.status"/><p v-if="p.status==='disabled'" class="disabled-reason">Disabled by Kisaku: {{p.status_reason}}</p></td><td><router-link :to="`/vendor/products/${p.id}/edit`">Edit</router-link></td></tr></tbody></table></div></main></template><style scoped>.vendor-main{padding:18px 28px}.page-head{display:flex;justify-content:space-between;align-items:center}.page-head p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.page-head h1{margin:4px 0 18px}.head-actions{display:flex;gap:8px}.primary,.secondary{height:42px;padding:0 14px;border-radius:6px;text-decoration:none;display:flex;align-items:center;gap:7px;font-weight:800}.primary{background:#ff7900;color:#fff}.secondary{border:1px solid #cbd5e1;background:#fff;color:#0f2a44}.filters{display:flex;gap:10px;margin-bottom:14px}.filters label{height:42px;min-width:260px;display:flex;align-items:center;gap:7px;padding:0 10px;border:1px solid #dbe3ec;border-radius:6px;background:#fff}.filters input{width:100%;border:0;outline:0}.filters select{height:42px;padding:0 10px;border:1px solid #dbe3ec;border-radius:6px;background:#fff}.product-table{border:1px solid #e6ebf1;border-radius:8px;background:#fff;overflow:hidden}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #edf0f3;text-align:left}th{color:#64748b;font-size:.72rem}.product-name{display:flex;align-items:center;gap:9px}.product-name img{width:42px;height:42px;border-radius:5px;object-fit:cover}.disabled-reason{max-width:260px;margin:5px 0 0;color:#b42318;font-size:.72rem}.low{color:#b42318;font-weight:750}.state{padding:30px;text-align:center;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.error{color:#b42318}@media(max-width:700px){.vendor-main{padding:14px}.page-head{align-items:flex-start}.head-actions{flex-direction:column}.filters{flex-direction:column}.filters label{min-width:0}.product-table{border:0;background:transparent}table,tbody,tr,td{display:block}thead{display:none}tr{margin-bottom:10px;padding:10px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}td{display:flex;justify-content:space-between;border:0;padding:7px}td::before{content:attr(data-label);color:#64748b;font-weight:700}}</style>